{
  "format": "glb-base64",
  "glb": "",
  "bytes": 13600,
  "nodes": [
    "socle_vitrine",
    "socle",
    "anneau"
  ]
}

// Bloom : halo lumineux autour des zones claires de l'image du canal 0 (néons, soleil, étincelles).
// Passe de clarté (seuil) puis flou par échantillonnage en spirale dorée, ajouté à l'image.
// uParam0 seuil (0..1), uParam1 intensité (0..3), uParam2 rayon (en millièmes du petit côté), uParam3 teinte du halo
// (0 = couleur d'origine, 1 = blanc chaud).
vec3 bright(vec2 uv, float th) {
  vec3 col = texture(iChannel0, uv).rgb;
  float l = dot(col, vec3(0.2126, 0.7152, 0.0722));
  return col * smoothstep(th, th + 0.15, l);
}

void mainImage(out vec4 c, in vec2 p) {
  vec2 uv = p / iResolution.xy;
  vec3 base = texture(iChannel0, uv).rgb;
  float th = clamp(uParam0, 0.0, 1.0);
  float radius = max(1.0, uParam2) * 0.001 * min(iResolution.x, iResolution.y);
  vec2 px = 1.0 / iResolution.xy;
  vec3 acc = vec3(0.0);
  float wsum = 0.0;
  for (int i = 0; i < 32; i++) {
    float fi = float(i) + 0.5;
    float r = sqrt(fi / 32.0);
    float a = fi * 2.39996323;
    vec2 o = vec2(cos(a), sin(a)) * r * radius * px;
    float w = 1.0 - r * 0.7;
    acc += bright(uv + o, th) * w;
    wsum += w;
  }
  vec3 glow = acc / wsum;
  glow = mix(glow, vec3(dot(glow, vec3(0.333))) * vec3(1.0, 0.92, 0.8), clamp(uParam3, 0.0, 1.0));
  c = vec4(base + glow * uParam1, 1.0);
}

// Dégradé vivant (« mesh gradient ») aux couleurs du thème : quatre taches de couleur qui dérivent lentement et
// se fondent, avec un grain léger. Couleurs : attribut `colors` (uColor0..3, ex. "--sc-base-50 --sc-accent
// --sc-deco-1 --sc-deco-2") ; sans attribut, une palette douce par défaut.
// uParam0 vitesse (0 = figé), uParam1 grain (0..0,2), uParam2 étalement des taches (0,2..1,5).
float dh12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }

vec3 pal(int i) {
  vec4 k = i == 0 ? uColor0 : i == 1 ? uColor1 : i == 2 ? uColor2 : uColor3;
  if (k.a > 0.0) return k.rgb;
  return i == 0 ? vec3(0.98, 0.95, 0.9) : i == 1 ? vec3(0.98, 0.55, 0.45) : i == 2 ? vec3(0.45, 0.6, 0.98) : vec3(0.98, 0.85, 0.35);
}

void mainImage(out vec4 c, in vec2 p) {
  vec2 uv = p / iResolution.xy;
  float aspect = iResolution.x / iResolution.y;
  vec2 q = vec2(uv.x * aspect, uv.y);
  float t = iTime * uParam0 * 0.15;
  float spread = clamp(uParam2, 0.2, 1.5);
  vec3 col = pal(0);
  float total = 1.0;
  for (int i = 1; i < 4; i++) {
    float fi = float(i);
    vec2 center = vec2(aspect * (0.5 + 0.42 * sin(t * (0.7 + 0.23 * fi) + fi * 2.1)), 0.5 + 0.42 * cos(t * (0.5 + 0.31 * fi) + fi * 1.3));
    float d = length(q - center);
    float w = exp(-d * d / (0.18 * spread * spread));
    col += pal(i) * w * 2.0;
    total += w * 2.0;
  }
  col /= total;
  col += (dh12(p + fract(iTime) * 100.0) - 0.5) * clamp(uParam1, 0.0, 0.2);
  c = vec4(col, 1.0);
}

// Tramage ordonné (matrice de Bayer 8x8) : réduit l'image à quelques niveaux.
float bayer2(vec2 a){ a = floor(a); return fract(a.x / 2.0 + a.y * a.y * 0.75); }
float bayer4(vec2 a){ return bayer2(0.5 * a) * 0.25 + bayer2(a); }
float bayer8(vec2 a){ return bayer4(0.5 * a) * 0.25 + bayer2(a); }
float lum(vec3 c){ return dot(c, vec3(0.299, 0.587, 0.114)); }
void mainImage(out vec4 o, in vec2 p){
  float size = max(1.0, floor(uParam0 + 0.5));
  vec2 cell = floor(p / size);
  vec2 uv = (cell + 0.5) * size / iResolution.xy;
  vec3 src = texture(iChannel0, uv).rgb;
  float levels = max(2.0, floor(uParam1 + 0.5));
  float thr = bayer8(cell) - 0.5;
  vec3 v = mix(vec3(lum(src)), src, uParam2);
  vec3 q = floor((v + thr / (levels - 1.0)) * (levels - 1.0) + 0.5) / (levels - 1.0);
  o = vec4(clamp(q, 0.0, 1.0), 1.0);
}

// Feu : flammes qui montent depuis le bas de l'image (bruit fractal déformé vers le haut), fond noir.
// À poser en fusion « screen » (mix-blend-mode) au-dessus d'une scène, ou comme fond.
// uParam0 vitesse, uParam1 hauteur des flammes (0,2..1,2), uParam2 couleur (0 braise orange → 1 flamme bleue),
// uParam3 largeur du foyer (0,1..1).
float fh12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }

float fnoise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(fh12(i), fh12(i + vec2(1.0, 0.0)), u.x), mix(fh12(i + vec2(0.0, 1.0)), fh12(i + vec2(1.0, 1.0)), u.x), u.y);
}

float ffbm(vec2 p) {
  float v = 0.0, a = 0.5;
  for (int i = 0; i < 5; i++) {
    v += a * fnoise(p);
    p = p * 2.03 + vec2(1.7, 9.2);
    a *= 0.5;
  }
  return v;
}

void mainImage(out vec4 c, in vec2 p) {
  vec2 uv = p / iResolution.xy;
  float aspect = iResolution.x / iResolution.y;
  float t = iTime * max(0.0, uParam0);
  vec2 q = vec2((uv.x - 0.5) * aspect, uv.y);
  float n = ffbm(vec2(q.x * 3.0, q.y * 2.0 - t * 1.6));
  float n2 = ffbm(vec2(q.x * 6.0 + n, q.y * 4.0 - t * 2.4));
  float width = clamp(uParam3, 0.1, 1.0) * aspect * 0.5;
  float base = 1.0 - smoothstep(width * 0.3, width, abs(q.x + (n - 0.5) * 0.25));
  float h = clamp(uParam1, 0.2, 1.2);
  float flame = base * (1.0 - uv.y / h) + (n2 - 0.5) * 0.9 * (1.0 - uv.y / (h * 1.3));
  flame = clamp(flame * 1.6, 0.0, 1.0);
  vec3 warm = vec3(1.6, 0.55, 0.12) * flame + vec3(0.6, 0.55, 0.4) * pow(flame, 4.0);
  vec3 cold = vec3(0.25, 0.55, 1.6) * flame + vec3(0.5, 0.6, 0.7) * pow(flame, 4.0);
  vec3 col = mix(warm, cold, clamp(uParam2, 0.0, 1.0)) * flame;
  c = vec4(col, 1.0);
}

// Finition d'une image (post-traitement) : effets indépendants de la résolution — le même réglage donne le
// même aspect à l'écran et dans un export ×4 (render-size). iChannel0 : l'image à finir (toile, export PNG).
// uParam0 effet : 0 aucun, 1 papier (grain et fibres), 2 trame ordonnée, 3 sérigraphie (repérage décalé,
// encres posterisées), 4 objectif (aberration chromatique et vignette). uParam1 intensité (0..1).
// uParam2 échelle du grain (millièmes du petit côté, 0.5..8).

float h12(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float vn(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(h12(i), h12(i + vec2(1.0, 0.0)), u.x), mix(h12(i + vec2(0.0, 1.0)), h12(i + vec2(1.0, 1.0)), u.x), u.y);
}

float bayer2(vec2 a) { a = floor(a); return fract(a.x / 2.0 + a.y * a.y * 0.75); }
float bayer4(vec2 a) { return bayer2(0.5 * a) * 0.25 + bayer2(a); }

void mainImage(out vec4 o, in vec2 f) {
  vec2 uv = f / iResolution.xy;
  float side = min(iResolution.x, iResolution.y);
  float k = clamp(uParam1, 0.0, 1.0);
  float scale = clamp(uParam2, 0.5, 8.0);
  // Coordonnées du grain : en millièmes du petit côté, donc identiques à toute résolution.
  vec2 g = f / side * 1000.0 / scale;
  int fx = int(uParam0 + 0.5);
  vec3 c = texture(iChannel0, uv).rgb;

  if (fx == 1) {
    float grain = vn(g * 0.9) * 0.5 + vn(g * 3.1) * 0.3 + h12(floor(g * 2.0)) * 0.2;
    float fibre = vn(vec2(g.x * 0.12, g.y * 2.4));
    vec3 paper = c * (0.9 + 0.2 * grain) * (0.97 + 0.06 * fibre) * vec3(1.0, 0.985, 0.95);
    c = mix(c, paper, k);
  } else if (fx == 2) {
    vec2 cell = floor(g / 2.5);
    float levels = 4.0;
    float thr = bayer4(cell) - 0.5;
    vec3 q = floor((c + thr / (levels - 1.0)) * (levels - 1.0) + 0.5) / (levels - 1.0);
    c = mix(c, clamp(q, 0.0, 1.0), k);
  } else if (fx == 3) {
    vec2 px = vec2(side) / iResolution.xy;
    float d = 0.004 * k;
    vec3 s;
    s.r = texture(iChannel0, uv + vec2(d, 0.6 * d) * px).r;
    s.g = texture(iChannel0, uv + vec2(-0.7 * d, 0.3 * d) * px).g;
    s.b = texture(iChannel0, uv + vec2(0.2 * d, -d) * px).b;
    vec3 ink = floor(s * 5.0 + 0.5) / 5.0;
    float grain = vn(g * 1.7);
    ink *= 0.94 + 0.12 * grain;
    c = mix(c, ink, k);
  } else if (fx == 4) {
    vec2 dir = uv - 0.5;
    float a = 0.012 * k;
    c.r = texture(iChannel0, uv + dir * a).r;
    c.b = texture(iChannel0, uv - dir * a).b;
    float vig = 1.0 - smoothstep(0.35, 0.95, length(dir) * 1.25);
    c *= mix(1.0, 0.55 + 0.45 * vig, k);
  }
  o = vec4(clamp(c, 0.0, 1.0), 1.0);
}

// Formes génératives à vectoriser (sonic-vectorize → sonic-sketch import-from). Image fixe (iTime non lu) :
// chaque réglage donne une image nette en aplats de quelques couleurs très distinctes sur fond noir (le
// vide : import-skip="#000000"), recolorées ensuite par la palette (import-colors-from).
// iChannel1 facultatif : bande de couleurs (une colonne de pixels par couleur, ex. image SVG de N×1) ; la
// couleur d'index i est alors la i-ème de la bande (modulo sa largeur) : aperçu et formes aux couleurs de la palette.
// uParam0 motif : 0 cellules, 1 courbes de niveau, 2 rosace, 3 entrelacs (Truchet), 4 taches,
// 5 rayures ondulées, 6 spirale, 7 écailles, 8 labyrinthe, 9 bouquet, 10 triangles, 11 damier ondulé,
// 12 ondes (interférences).
// uParam1 graine. uParam2 densité (1..10). uParam3 nombre de couleurs (2..6).

float hash1(vec2 p, float s) {
  return fract(sin(dot(p, vec2(12.9898, 78.233)) + s * 7.31) * 43758.5453);
}

vec2 hash2(vec2 p, float s) {
  vec2 q = vec2(dot(p, vec2(127.1, 311.7)) + s * 17.13, dot(p, vec2(269.5, 183.3)) + s * 31.7);
  return fract(sin(q) * 43758.5453);
}

float vnoise(vec2 p, float s) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  float a = hash1(i, s);
  float b = hash1(i + vec2(1.0, 0.0), s);
  float c = hash1(i + vec2(0.0, 1.0), s);
  float d = hash1(i + vec2(1.0, 1.0), s);
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p, float s) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 5; i++) {
    v += a * vnoise(p, s);
    p = p * 2.03 + vec2(1.7, 9.2);
    a *= 0.5;
  }
  return v;
}

// Couleurs d'index très écartées : la vectorisation les sépare sans ambiguïté.
vec3 bandColor(int i) {
  if (i == 0) return vec3(1.0, 0.0, 0.0);
  if (i == 1) return vec3(0.0, 0.8, 0.0);
  if (i == 2) return vec3(0.0, 0.0, 1.0);
  if (i == 3) return vec3(1.0, 1.0, 0.0);
  if (i == 4) return vec3(1.0, 0.0, 1.0);
  return vec3(0.0, 1.0, 1.0);
}

void mainImage(out vec4 o, in vec2 f) {
  // Carré centré : -0.5..0.5 sur le petit côté.
  vec2 uv = (f - 0.5 * iResolution.xy) / min(iResolution.x, iResolution.y);
  int motif = int(uParam0 + 0.5);
  float seed = floor(uParam1 + 0.5);
  float dens = clamp(uParam2, 1.0, 10.0);
  int n = int(clamp(uParam3 + 0.5, 2.0, 6.0));
  float nf = float(n);
  int idx = -1;

  if (motif == 0) {
    // Cellules de Voronoï séparées par un joint vide.
    vec2 p = uv * dens * 2.0;
    vec2 g = floor(p);
    vec2 fr = fract(p);
    float d1 = 8.0;
    float d2 = 8.0;
    vec2 best = vec2(0.0);
    for (int y = -1; y <= 1; y++) {
      for (int x = -1; x <= 1; x++) {
        vec2 c = vec2(float(x), float(y));
        vec2 r = c + hash2(g + c, seed) - fr;
        float d = dot(r, r);
        if (d < d1) { d2 = d1; d1 = d; best = g + c; }
        else if (d < d2) { d2 = d; }
      }
    }
    if (sqrt(d2) - sqrt(d1) > 0.08) idx = int(hash1(best, seed + 3.0) * nf);
  } else if (motif == 1) {
    // Courbes de niveau d'un bruit : bandes séparées par un trait vide.
    float t = fbm(uv * dens * 1.5 + seed * 3.1, seed) * (nf + 1.0);
    float k = floor(t);
    if (k >= 1.0 && fract(t) > 0.12) idx = int(mod(k - 1.0, nf));
  } else if (motif == 2) {
    // Rosace : pétales en anneaux concentriques.
    float r = length(uv) * 2.0;
    float a = atan(uv.y, uv.x);
    float k = floor(2.0 + dens);
    float petal = 0.55 + 0.35 * cos(k * a + seed * 0.7);
    if (r < petal) {
      float t = r / petal * nf;
      if (t < 1.0 || fract(t) > 0.1) idx = int(min(floor(t), nf - 1.0));
    }
  } else if (motif == 3) {
    // Entrelacs de Truchet : arcs de quart de cercle, une couleur par arc.
    vec2 p = uv * dens * 2.0;
    vec2 g = floor(p);
    vec2 fr = fract(p) - 0.5;
    if (hash1(g, seed) > 0.5) fr.x = -fr.x;
    float da = abs(length(fr - vec2(0.5)) - 0.5);
    float db = abs(length(fr + vec2(0.5)) - 0.5);
    if (min(da, db) < 0.16) idx = int(hash1(g + (da < db ? vec2(0.3) : vec2(0.7)), seed + 5.0) * nf);
  } else if (motif == 5) {
    // Rayures ondulées : bandes déformées par un bruit, séparées par un trait vide.
    float w = fbm(uv * 2.0 + seed * 1.3, seed) * 1.6;
    float t = (uv.y + 0.18 * sin(uv.x * 6.0 + seed) + w * 0.25) * dens * 2.2;
    if (fract(t) > 0.14) idx = int(mod(floor(t) + 100.0, nf));
  } else if (motif == 6) {
    // Spirale : bras logarithmiques.
    float r = length(uv) + 1e-4;
    float a = atan(uv.y, uv.x);
    // Nombre de bras multiple du nombre de couleurs : pas de couture à l'angle ±π.
    float arms = nf * floor(1.0 + dens * 0.25);
    float t = (a / 6.2831853) * arms + log(r) * (1.2 + 0.25 * mod(seed, 5.0)) * 2.0;
    if (r < 0.62 && fract(t) > 0.16) idx = int(mod(floor(t) + 100.0, nf));
  } else if (motif == 7) {
    // Écailles : rangées de disques décalées, chaque rangée recouvre celle du dessus ; joint vide.
    vec2 p = uv * dens * 2.4;
    float j = floor(p.y);
    for (int dy = -1; dy <= 1; dy++) {
      float row = j + float(dy);
      float off = mod(row, 2.0) * 0.5;
      float cx = floor(p.x - off + 0.5) + off;
      vec2 ctr = vec2(cx, row);
      float d = length(p - ctr);
      if (d < 0.7) idx = d < 0.62 ? int(hash1(ctr, seed + 2.0) * nf) : -1;
    }
  } else if (motif == 8) {
    // Labyrinthe : diagonales épaisses de Truchet, une couleur par case.
    vec2 p = uv * dens * 2.6;
    vec2 g = floor(p);
    vec2 fr = fract(p);
    float s = hash1(g, seed) > 0.5 ? fr.x - fr.y : fr.x + fr.y - 1.0;
    if (abs(s) < 0.22) idx = int(hash1(g + 0.37, seed + 4.0) * nf);
  } else if (motif == 9) {
    // Bouquet : fleurs éparses à pétales, cœur d'une autre couleur.
    for (int i = 0; i < 18; i++) {
      vec2 c = (hash2(vec2(float(i), 11.0), seed) - 0.5) * 0.9;
      float sz = (0.08 + 0.09 * hash1(vec2(float(i), 5.0), seed)) * (4.0 / (2.0 + dens * 0.4));
      vec2 d = uv - c;
      float r = length(d) / sz;
      float a = atan(d.y, d.x);
      float k = 5.0 + floor(hash1(vec2(float(i), 2.0), seed) * 4.0);
      float pet = 0.65 + 0.35 * cos(k * a);
      if (r < 0.32) idx = int(mod(float(i) + 1.0, nf));
      else if (r < pet && r > 0.4) idx = int(mod(float(i), nf));
    }
  } else if (motif == 10) {
    // Triangles : pavage triangulaire, joints vides.
    vec2 p = uv * dens * 2.4;
    vec2 q = vec2(p.x - p.y * 0.57735, p.y * 1.1547);
    vec2 g = floor(q);
    vec2 fr = fract(q);
    float up = step(fr.x + fr.y, 1.0);
    float e = up > 0.5 ? min(min(fr.x, fr.y), 1.0 - fr.x - fr.y) : min(min(1.0 - fr.x, 1.0 - fr.y), fr.x + fr.y - 1.0);
    if (e > 0.06) idx = int(hash1(g + up * 0.5, seed + 6.0) * nf);
  } else if (motif == 11) {
    // Damier ondulé : damier déformé par un bruit.
    vec2 p = uv * dens * 1.8;
    p += vec2(fbm(p * 0.6 + seed, seed), fbm(p * 0.6 - seed, seed + 1.0)) * 1.4;
    vec2 g = floor(p);
    vec2 fr = fract(p);
    if (min(min(fr.x, fr.y), min(1.0 - fr.x, 1.0 - fr.y)) > 0.07) idx = int(mod(g.x + g.y * 2.0 + 64.0, nf));
  } else if (motif == 12) {
    // Ondes : interférences de trois sources circulaires.
    float v = 0.0;
    for (int i = 0; i < 3; i++) {
      vec2 c = (hash2(vec2(float(i), 21.0), seed) - 0.5) * 0.9;
      v += sin(length(uv - c) * dens * 9.0);
    }
    float t = (v + 3.0) / 6.0 * (nf + 0.999);
    if (fract(t) > 0.12) idx = int(min(floor(t), nf - 1.0));
  } else {
    // Taches : champ de métaballes en anneaux.
    float v = 0.0;
    for (int i = 0; i < 12; i++) {
      vec2 c = (hash2(vec2(float(i), 3.0), seed) - 0.5) * 0.85;
      float rad = 0.03 + 0.06 * hash1(vec2(float(i), 7.0), seed);
      vec2 d = uv - c;
      v += rad * rad / max(dot(d, d), 1e-5);
    }
    v *= dens * 0.25;
    if (v > 1.0) {
      float t = log2(v) * nf / 3.0;
      if (t < 1.0 || fract(t) > 0.1) idx = int(min(floor(t), nf - 1.0));
    }
  }

  if (idx < 0) { o = vec4(0.0, 0.0, 0.0, 1.0); return; }
  float pw = floor(iChannelResolution[1].x + 0.5);
  if (pw >= 1.0) {
    float k = mod(float(idx), pw);
    o = vec4(texture(iChannel1, vec2((k + 0.5) / pw, 0.5)).rgb, 1.0);
  } else {
    o = vec4(bandColor(idx), 1.0);
  }
}

// Glitch : bandes décalées, canaux RVB séparés, blocs corrompus, lignes de balayage.
// Même algorithme que l'effet `glitch` de la pile post de procgen, pour une image du canal 0.
// uParam0 quantité (0 = image propre), uParam1 bandes, uParam2 décalage RVB (px), uParam3 vitesse (0 = figé).
float gh12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }

void mainImage(out vec4 c, in vec2 p){
  vec2 uv = p / iResolution.xy;
  float amount = clamp(uParam0, 0.0, 1.0);
  float bands = clamp(uParam1, 4.0, 80.0);
  float t = floor(iTime * uParam3 * 8.0);
  float by = floor(uv.y * bands);
  float on = step(1.0 - amount * 0.6, gh12(vec2(by, t)));
  float shift = (gh12(vec2(by * 1.7, t + 5.1)) - 0.5) * 0.2 * on * amount;
  float bb = floor(uv.y * bands * 0.25);
  float big = step(1.0 - amount * 0.25, gh12(vec2(bb, t + 2.0)));
  shift += (gh12(vec2(bb, t + 9.0)) - 0.5) * 0.12 * big;
  vec2 u = vec2(fract(uv.x + shift), uv.y);
  vec2 s = vec2(uParam2 / iResolution.x, 0.0) * (0.35 + on + big) * step(0.001, amount);
  vec3 col = vec3(texture(iChannel0, u + s).r, texture(iChannel0, u).g, texture(iChannel0, u - s).b);
  vec2 blk = floor(uv * vec2(bands * 0.5, bands));
  if (gh12(blk + t * 1.3) > 1.0 - amount * 0.07) {
    vec2 g = vec2(48.0, 32.0);
    col = texture(iChannel0, (floor(u * g) + 0.5) / g).brg;
  }
  c = vec4(col * (1.0 - 0.18 * on * step(0.5, fract(p.y * 0.5))), 1.0);
}

// Similigravure : points dont la taille suit la luminance, grille inclinée.
float lum(vec3 c){ return dot(c, vec3(0.299, 0.587, 0.114)); }
void mainImage(out vec4 o, in vec2 p){
  float s = max(3.0, uParam0);
  float a = uParam1;
  mat2 R = mat2(cos(a), -sin(a), sin(a), cos(a));
  vec2 q = (R * p) / s;
  vec2 g = floor(q) + 0.5;
  vec2 f = fract(q) - 0.5;
  vec2 centre = (g * s) * R;          // R est orthonormale : v * R = transpose(R) * v
  vec3 src = texture(iChannel0, clamp(centre / iResolution.xy, 0.0, 1.0)).rgb;
  float r = sqrt(1.0 - lum(src)) * 0.7071;
  float m = 1.0 - smoothstep(r - 0.1, r, length(f));
  vec3 ink = mix(vec3(0.0), src, uParam2);
  o = vec4(mix(vec3(1.0), ink, m), 1.0);
}

// Détecteur de coins de Harris (une passe, fenêtre gaussienne 5x5, k = 0,05).
// Pas de suppression des non-maxima (il faudrait une seconde passe) : les coins apparaissent comme des taches.
float lum(vec3 c){ return dot(c, vec3(0.299, 0.587, 0.114)); }
float L(vec2 uv){ return lum(texture(iChannel0, uv).rgb); }
void mainImage(out vec4 o, in vec2 p){
  vec2 uv = p / iResolution.xy;
  vec2 t = max(uParam0, 1.0) / iChannelResolution[0].xy;
  float sxx = 0.0, syy = 0.0, sxy = 0.0;
  for (int j = -2; j <= 2; j++) {
    for (int i = -2; i <= 2; i++) {
      vec2 q = uv + t * vec2(float(i), float(j));
      float ix = L(q + vec2(t.x, 0.0)) - L(q - vec2(t.x, 0.0));
      float iy = L(q + vec2(0.0, t.y)) - L(q - vec2(0.0, t.y));
      float w = exp(-float(i * i + j * j) / 4.0);
      sxx += w * ix * ix; syy += w * iy * iy; sxy += w * ix * iy;
    }
  }
  float det = sxx * syy - sxy * sxy;
  float tr = sxx + syy;
  float r = (det - 0.05 * tr * tr) * uParam1;
  float corner = smoothstep(uParam2, uParam2 + 0.25, r);
  vec3 base = texture(iChannel0, uv).rgb;
  o = vec4(mix(base * 0.55, vec3(1.0, 0.25, 0.1), corner), 1.0);
}

// Transformée de Hough des cercles de rayon fixe, en une passe.
// Entrée (canal 0) : une CARTE DE CONTOURS (sonic-shader sobel en mode 0, channel0="#contours").
// Chaque pixel de sortie est un centre candidat : son score est la moyenne des contours sur le cercle
// de rayon uParam0 (en hauteurs d'image) autour de lui. Pic lumineux = centre d'un cercle de ce rayon.
// Coût : 64 lectures par pixel.
void mainImage(out vec4 o, in vec2 p){
  vec2 uv = p / iResolution.xy;
  float asp = iChannelResolution[0].x / iChannelResolution[0].y;
  vec2 ext = vec2(asp, 1.0);
  vec2 c = (uv - 0.5) * ext;
  float r = max(uParam0, 0.01);
  float acc = 0.0;
  for (int k = 0; k < 64; k++) {
    float a = (float(k) + 0.5) / 64.0 * 6.2831853;
    vec2 q = (c + r * vec2(cos(a), sin(a))) / ext + 0.5;
    if (q.x >= 0.0 && q.x <= 1.0 && q.y >= 0.0 && q.y <= 1.0) acc += dot(texture(iChannel0, q).rgb, vec3(0.3333));
  }
  float v = clamp((acc / 64.0) * uParam1 - uParam2, 0.0, 1.0);
  vec3 edges = vec3(dot(texture(iChannel0, uv).rgb, vec3(0.3333)));
  vec3 hot = vec3(clamp(v * 3.0, 0.0, 1.0), clamp(v * 3.0 - 1.0, 0.0, 1.0), clamp(v * 3.0 - 2.0, 0.0, 1.0));
  o = vec4(max(hot, edges * 0.35 * step(0.5, uParam3)), 1.0);
}

// Transformée de Hough des droites, en une passe (force brute le long de chaque droite).
// Entrée (canal 0) : une CARTE DE CONTOURS, par exemple un sonic-shader sobel en mode 0 (channel0="#contours").
// Sortie : l'espace de Hough. x = angle theta (0..pi), y = distance rho (-R..R) depuis le centre de l'image.
// Un point lumineux = une droite de l'image (theta, rho). Pas de détection de pics (il faudrait une seconde passe).
// Coût : 96 lectures par pixel de sortie : afficher en petit (par ex. 360 x 240).
void mainImage(out vec4 o, in vec2 p){
  vec2 uv = p / iResolution.xy;
  float asp = iChannelResolution[0].x / iChannelResolution[0].y;
  vec2 ext = vec2(asp, 1.0);
  float rmax = 0.5 * length(ext);
  float th = uv.x * 3.14159265;
  float rho = (uv.y * 2.0 - 1.0) * rmax;
  vec2 n = vec2(cos(th), sin(th));
  vec2 d = vec2(-n.y, n.x);
  float acc = 0.0;
  float cnt = 0.0;
  for (int k = 0; k < 96; k++) {
    float s = ((float(k) + 0.5) / 96.0 * 2.0 - 1.0) * rmax;
    vec2 q = (rho * n + s * d) / ext + 0.5;
    if (q.x >= 0.0 && q.x <= 1.0 && q.y >= 0.0 && q.y <= 1.0) {
      acc += dot(texture(iChannel0, q).rgb, vec3(0.3333));
      cnt += 1.0;
    }
  }
  float v = cnt > 8.0 ? acc / cnt : 0.0;
  v = clamp((v * uParam0 - uParam1) / max(1.0 - uParam1, 0.001), 0.0, 1.0);
  vec3 hot = vec3(clamp(v * 3.0, 0.0, 1.0), clamp(v * 3.0 - 1.0, 0.0, 1.0), clamp(v * 3.0 - 2.0, 0.0, 1.0));
  o = vec4(hot, 1.0);
}

// Kaléidoscope sur l'image du canal 0 (caméra, vidéo, image).
void mainImage(out vec4 c, in vec2 p){
  vec2 uv = p / iResolution.xy;
  vec2 q = uv - 0.5; q.x *= iResolution.x / iResolution.y;
  float n = max(2.0, floor(uParam0 + 0.5));
  float a = atan(q.y, q.x) + iTime * uParam1; float r = length(q);
  a = mod(a, 6.2831853 / n); a = abs(a - 3.1415926 / n);
  uv = 0.5 + r * vec2(cos(a) * iResolution.y / iResolution.x, sin(a));
  c = vec4(texture(iChannel0, uv).rgb, 1.0);
}

// Niveaux d'une image (canal 0), en gris : luminosité, contraste, gamma, et égalisation de l'éclairage.
// Sert à préparer une photo avant un tramage ou une gravure (sonic-gcode source="#id" de ce shader).
// uParam0 luminosité (-1..1), uParam1 contraste (-1..1), uParam2 gamma (0.2..3 ; 1 neutre, < 1 éclaircit
// les tons moyens), uParam3 éclairage local (0..1) : divise par le fond (moyenne large) pour retirer ombres
// et dégradés lents ; un seuil ou un tramage garde alors le détail dans les zones sombres et claires.
float lum(vec3 c) { return dot(c, vec3(0.299, 0.587, 0.114)); }

void mainImage(out vec4 o, in vec2 f) {
  vec2 uv = f / iResolution.xy;
  float v = lum(texture(iChannel0, uv).rgb);
  float k = clamp(uParam3, 0.0, 1.0);
  if (k > 0.0) {
    // Fond : moyenne de 3 anneaux de 12 points, jusqu'à 12 % du petit côté.
    float side = min(iChannelResolution[0].x, iChannelResolution[0].y);
    vec2 px = vec2(side) / iChannelResolution[0].xy;
    float bg = v;
    float n = 1.0;
    for (int r = 1; r <= 3; r++) {
      float rad = 0.04 * float(r);
      for (int i = 0; i < 12; i++) {
        float a = float(i) * 0.5235988 + float(r) * 0.3;
        bg += lum(textureLod(iChannel0, clamp(uv + vec2(cos(a), sin(a)) * rad * px, 0.0, 1.0), 0.0).rgb);
        n += 1.0;
      }
    }
    bg /= n;
    float aplani = clamp(v / max(bg, 0.03) * 0.78, 0.0, 1.0);
    v = mix(v, aplani, k);
  }
  float c = clamp(uParam1, -1.0, 1.0);
  float factor = c >= 0.0 ? 1.0 + c * 3.0 : 1.0 + c;
  v = clamp((v - 0.5) * factor + 0.5 + clamp(uParam0, -1.0, 1.0) * 0.5, 0.0, 1.0);
  float g = uParam2 > 0.0 ? clamp(uParam2, 0.2, 3.0) : 1.0;
  v = pow(v, g);
  o = vec4(vec3(v), 1.0);
}

// Pile d'effets cumulables pour finir une image (post-traitement), appliqués dans un ordre fixe :
// géométrie → lumière → couleur → matière. Indépendant de la résolution : le même réglage donne le même
// aspect à l'écran et dans un export ×4 (render-size). iChannel0 : l'image à traiter.
// uParam0 : masque des effets actifs, somme de 2^i pour chaque effet i :
//   géométrie  0 miroir, 1 kaléido, 2 tourbillon, 3 ondes, 4 pixels
//   lumière    5 prisme, 6 halo, 7 flou, 8 encre (contours)
//   couleur    9 éclat, 10 teinte, 11 bichromie, 12 sépia, 13 aplats, 14 négatif, 15 thermique
//   matière   16 papier, 17 trame, 18 points, 19 hachures, 20 balayage, 21 grain, 22 vignette
// uParam2 : second masque (somme de 2^i) :
//   matière picturale  0 peinture (huile, Kuwahara), 1 mosaïque, 2 pointillisme
//   traits             3 contour (dessin au trait), 4 néon, 5 gaufrage
//   médiums            6 aquarelle, 7 crayonné
// uParam1 intensité (0..1). uParam3 = grain + teinte : partie entière = échelle du grain × 2 (1..16, soit
// 0,5..8 millièmes du petit côté ; 0 = défaut 2), partie fractionnaire = teinte (0..1).

const float PI = 3.14159265;

bool fxOn(int i) {
  return mod(floor((uParam0 + 0.5) / exp2(float(i))), 2.0) >= 1.0;
}

bool fxB(int i) {
  return mod(floor((uParam2 + 0.5) / exp2(float(i))), 2.0) >= 1.0;
}

vec2 h22(vec2 p) {
  return fract(sin(vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)))) * 43758.5453);
}

float h12(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float vn(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(h12(i), h12(i + vec2(1.0, 0.0)), u.x), mix(h12(i + vec2(0.0, 1.0)), h12(i + vec2(1.0, 1.0)), u.x), u.y);
}

float bayer2(vec2 a) { a = floor(a); return fract(a.x / 2.0 + a.y * a.y * 0.75); }
float bayer4(vec2 a) { return bayer2(0.5 * a) * 0.25 + bayer2(a); }

float luma(vec3 c) { return dot(c, vec3(0.299, 0.587, 0.114)); }

// Rotation de teinte autour de l'axe des gris (formule de Rodrigues).
vec3 hueTurn(vec3 c, float a) {
  vec3 k = vec3(0.57735);
  float ca = cos(a);
  return c * ca + cross(k, c) * sin(a) + k * dot(k, c) * (1.0 - ca);
}

// Couleur pure d'une teinte h (0..1).
vec3 hueColor(float h) {
  return clamp(abs(mod(h * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
}

vec3 tap(vec2 uv) {
  return texture(iChannel0, clamp(uv, 0.0, 1.0)).rgb;
}

// Peinture : filtre de Kuwahara (4 quadrants, on garde la moyenne du plus homogène) — aplats « coup de pinceau ».
vec3 kuwahara(vec2 uv, vec2 st) {
  vec3 m0 = vec3(0.0), m1 = vec3(0.0), m2 = vec3(0.0), m3 = vec3(0.0);
  vec3 s0 = vec3(0.0), s1 = vec3(0.0), s2 = vec3(0.0), s3 = vec3(0.0);
  for (int j = -3; j <= 3; j++) {
    for (int i = -3; i <= 3; i++) {
      vec3 c = tap(uv + vec2(float(i), float(j)) * st);
      vec3 c2 = c * c;
      if (i <= 0 && j <= 0) { m0 += c; s0 += c2; }
      if (i >= 0 && j <= 0) { m1 += c; s1 += c2; }
      if (i <= 0 && j >= 0) { m2 += c; s2 += c2; }
      if (i >= 0 && j >= 0) { m3 += c; s3 += c2; }
    }
  }
  m0 /= 16.0; m1 /= 16.0; m2 /= 16.0; m3 /= 16.0;
  vec3 v0 = abs(s0 / 16.0 - m0 * m0), v1 = abs(s1 / 16.0 - m1 * m1), v2 = abs(s2 / 16.0 - m2 * m2), v3 = abs(s3 / 16.0 - m3 * m3);
  float a = v0.r + v0.g + v0.b, b = v1.r + v1.g + v1.b, c = v2.r + v2.g + v2.b, d = v3.r + v3.g + v3.b;
  vec3 best = m0; float bv = a;
  if (b < bv) { bv = b; best = m1; }
  if (c < bv) { bv = c; best = m2; }
  if (d < bv) { best = m3; }
  return best;
}

// Gradient de luminance (Sobel léger) autour de uv, pas e (coordonnées de texture).
float edgeAt(vec2 uv, vec2 e) {
  float tl = luma(tap(uv + vec2(-e.x, e.y))), t = luma(tap(uv + vec2(0.0, e.y))), tr = luma(tap(uv + e));
  float l = luma(tap(uv - vec2(e.x, 0.0))), r = luma(tap(uv + vec2(e.x, 0.0)));
  float bl = luma(tap(uv - e)), b = luma(tap(uv - vec2(0.0, e.y))), br = luma(tap(uv + vec2(e.x, -e.y)));
  float gx = (tr + 2.0 * r + br) - (tl + 2.0 * l + bl);
  float gy = (tl + 2.0 * t + tr) - (bl + 2.0 * b + br);
  return length(vec2(gx, gy));
}

void mainImage(out vec4 o, in vec2 f) {
  vec2 R = iResolution.xy;
  float side = min(R.x, R.y);
  float k = clamp(uParam1, 0.0, 1.0);
  float gi = floor(uParam3);
  float scale = gi < 0.5 ? 2.0 : clamp(gi * 0.5, 0.5, 8.0);
  float hue = fract(uParam3);
  vec3 paperC = vec3(0.97, 0.955, 0.92);
  // Grain : en millièmes du petit côté (identique à toute résolution).
  vec2 g = f / side * 1000.0 / scale;
  // Un millième du petit côté, en coordonnées de texture.
  vec2 mil = vec2(side / 1000.0) / R;

  // --- Géométrie : p centré, petit côté = 1.
  vec2 p = (f / R - 0.5) * R / side;
  if (fxOn(0)) p.x = -abs(p.x);
  if (fxOn(1)) {
    float s = 2.0 * PI / 6.0;
    float a = mod(atan(p.y, p.x), s);
    // L'intensité fait tourner le secteur échantillonné ; décalé du centre pour mêler plusieurs formes.
    a = abs(a - 0.5 * s) + k * 2.0 * PI;
    p = length(p) * 1.15 * vec2(cos(a), sin(a)) + vec2(-0.12, 0.04);
  }
  if (fxOn(2)) {
    float a = (1.0 - smoothstep(0.0, 0.7, length(p))) * (1.0 + 3.0 * k);
    p = mat2(cos(a), -sin(a), sin(a), cos(a)) * p;
  }
  if (fxOn(3)) p += (0.004 + 0.012 * k) * vec2(sin(p.y * 38.0), sin(p.x * 38.0));
  if (fxOn(4)) {
    float cell = mix(0.006, 0.04, k);
    p = (floor(p / cell) + 0.5) * cell;
  }
  vec2 uv = p * side / R + 0.5;

  // --- Matière picturale : la couleur de base vient d'un voisinage (après la géométrie).
  vec3 c = tap(uv);
  vec2 fw = uv * R;
  if (fxB(0)) c = kuwahara(uv, mil * (1.2 + 2.3 * k));
  if (fxB(1)) {
    float cell = mix(14.0, 55.0, k);
    vec2 q = fw / side * 1000.0 / cell;
    vec2 ip = floor(q), fp = fract(q);
    float d1 = 8.0, d2 = 8.0;
    vec2 best = ip;
    for (int j = -1; j <= 1; j++) {
      for (int i = -1; i <= 1; i++) {
        vec2 o = vec2(float(i), float(j));
        vec2 pt = o + 0.1 + 0.8 * h22(ip + o);
        float d = length(pt - fp);
        if (d < d1) { d2 = d1; d1 = d; best = ip + pt; } else if (d < d2) { d2 = d; }
      }
    }
    vec3 cc = tap(best * cell / 1000.0 * side / R);
    c = mix(cc * 0.55, cc, smoothstep(0.0, 0.07, d2 - d1));
  }
  if (fxB(2)) {
    float cell = mix(4.0, 12.0, k);
    vec2 q = fw / side * 1000.0 / cell;
    vec2 ip = floor(q);
    vec3 col = paperC;
    for (int j = -1; j <= 1; j++) {
      for (int i = -1; i <= 1; i++) {
        vec2 o = vec2(float(i), float(j));
        vec2 hh = h22(ip + o + 17.0);
        vec2 ctr = ip + o + 0.5 + (hh - 0.5) * 0.7;
        float rad = 0.5 + 0.3 * hh.x;
        if (length(q - ctr) < rad) col = tap(ctr * cell / 1000.0 * side / R) * (0.92 + 0.16 * hh.y);
      }
    }
    c = col;
  }

  // --- Lumière.
  if (fxOn(5)) {
    vec2 d = (uv - 0.5) * (0.004 + 0.016 * k);
    c.r = tap(uv + d).r;
    c.b = tap(uv - d).b;
  }
  if (fxOn(6) || fxOn(7)) {
    vec3 b = vec3(0.0);
    float rr = 10.0 + 14.0 * k;
    for (int i = 0; i < 12; i++) {
      float a = float(i) * PI / 6.0;
      b += tap(uv + vec2(cos(a), sin(a)) * rr * mil);
      b += tap(uv + vec2(cos(a + 0.26), sin(a + 0.26)) * rr * 0.45 * mil);
    }
    b /= 24.0;
    if (fxOn(7)) c = mix(c, b, 0.4 + 0.6 * k);
    if (fxOn(6)) c = 1.0 - (1.0 - c) * (1.0 - b * b * (0.5 + 0.7 * k));
  }
  if (fxOn(8)) {
    vec2 e = 1.6 * mil;
    float gx = luma(tap(uv + vec2(e.x, 0.0))) - luma(tap(uv - vec2(e.x, 0.0)));
    float gy = luma(tap(uv + vec2(0.0, e.y))) - luma(tap(uv - vec2(0.0, e.y)));
    float edge = smoothstep(0.05, 0.2, length(vec2(gx, gy)));
    c *= 1.0 - edge * (0.5 + 0.45 * k);
  }

  // --- Traits.
  if (fxB(3) || fxB(4)) {
    float ed = edgeAt(uv, mil * (1.0 + 1.5 * k));
    if (fxB(3)) {
      float ink = smoothstep(0.12, 0.45, ed);
      vec3 inkC = mix(vec3(0.08, 0.07, 0.07), c * 0.35, 0.35);
      c = mix(paperC, inkC, ink);
    }
    if (fxB(4)) {
      float glow = smoothstep(0.08, 0.6, ed);
      vec3 neon = mix(normalize(c + 0.05) * 1.25, hueColor(hue), 0.35);
      c = vec3(0.015, 0.012, 0.03) + neon * glow * (0.9 + 0.6 * k) + c * 0.06;
    }
  }
  if (fxB(5)) {
    vec2 e = mil * (1.5 + 2.0 * k);
