vec3 target(vec2 cell){
  vec2 cs = gCell / iResolution.xy;
  vec3 a = nearMean(cell, cs);
  if (gLis > 0.01) a = mix(a, kuwahara(cell, cs), gLis);
  return grade(oklab(a));
