  // dégradé) : un dégradé change des deux côtés du pixel et dans le même sens ; un bord d'un seul côté,
  // un aplat nulle part, le bruit dans tous les sens.
  float gx = pente(c[1] - c[0], c[0] - c[2]), gy = pente(c[3] - c[0], c[0] - c[4]);
  float grad = smoothstep(0.0015, 0.006, max(gx, gy));

  // Palette
  gN = 0;
  if (p >= 1) gN = PAL_CNT[p - 1];
  else for (int i = 0; i < 8; i++){ if (uColor(i).a > 0.0) gN++; else break; }
  if (gN < 2){
    // Sans palette : niveaux OKLab (luminance 7 crans, chroma 5) tramés.
    vec3 lv = vec3(6.0, 10.0, 10.0);
    vec3 q = floor(c[0] * lv + vec3(0.0, 5.0, 5.0) + mix(vec3(0.5), vec3(trame(cell)), dith));
    o = vec4(clamp(fromOklab((q - vec3(0.0, 5.0, 5.0)) / lv), 0.0, 1.0), 1.0);
    return;
  }
  bool mono = p == 2 || p == 10;
  float lo = 1e9, hi = -1e9;
  for (int i = 0; i < 16; i++){
    if (i >= gN) break;
    gLab[i] = oklab(p >= 1 ? PAL[PAL_OFF[p - 1] + i] : uColor(i).rgb);
    lo = min(lo, gLab[i].x); hi = max(hi, gLab[i].x);
  }
  if (mono){
    for (int i = 0; i < 16; i++){ if (i >= gN) break; gLab[i] = vec3(gLab[i].x, 0.0, 0.0); }
    for (int k = 0; k < 5; k++) c[k] = vec3(mix(lo, hi, smoothstep(0.08, 0.92, c[k].x)), 0.0, 0.0);
  }
  int idx[5];
  for (int k = 0; k < 5; k++) idx[k] = nearest(c[k]);
  int i0 = idx[0];

  // Nettoyage sur les index : seul de sa couleur parmi 4 voisins qui s'accordent (3 sur 4) → leur couleur.
  bool orphan = false;
  if (idx[1] != i0 && idx[2] != i0 && idx[3] != i0 && idx[4] != i0){
    for (int k = 1; k < 5; k++){
      int n = 0;
      for (int j = 1; j < 5; j++) if (idx[j] == idx[k]) n++;
      if (n >= 3){
        if (length(c[0] - gLab[idx[k]]) < 0.18){ i0 = idx[k]; c[0] = gLab[i0]; orphan = true; }
        break;
      }
    }
  }

  // Contour : côté sombre d'un bord franc (sur les couleurs cibles), couleur d'un cran plus sombre.
  bool outline = false;
  if (edge > 0.0){
    float th = mix(0.32, 0.07, edge);
    for (int k = 1; k < 5; k++){
      vec3 d = c[k] - c[0];
      int op = k == 1 ? 2 : k == 2 ? 1 : k == 3 ? 4 : 3;  // voisin opposé : un bord n'a qu'un côté (le bruit en a deux)
      if (idx[k] != i0 && length(d * vec3(1.6, 1.0, 1.0)) > th && d.x > mix(0.16, 0.06, edge) && length(c[op] - c[0]) < 0.5 * th) outline = true;
    }
  }
  if (outline) i0 = rampDown(i0);

  // Tramage de Knoll : 4 candidates par diffusion d'erreur locale, rangées par luminance, motif 2×2.
  int outI = i0;
  float s = (outline || orphan) ? 0.0 : dith * grad;
  if (s > 0.0){
    int cand[4];
    vec3 e = vec3(0.0);
    float gap = mix(0.2, 0.42, s);
    for (int k = 0; k < 4; k++){
      int ik = nearest(c[0] + e * s);
      if (length(gLab[ik] - c[0]) > gap) ik = i0;
      cand[k] = ik;
      e += c[0] - gLab[ik];
    }
    // Deux couleurs par motif au plus (pixel art) : la cible et la première autre candidate.
    int i2 = i0;
    for (int k = 0; k < 4; k++) if (i2 == i0 && cand[k] != i0) i2 = cand[k];
    for (int k = 0; k < 4; k++) if (cand[k] != i0 && cand[k] != i2) cand[k] = perr(gLab[cand[k]], gLab[i0]) < perr(gLab[cand[k]], gLab[i2]) ? i0 : i2;
    // Le motif n'est gardé que s'il approche mieux la cible que la couleur seule, son contraste compté
    // (pénalité de Yliluoma, d'autant plus faible que le tramage est fort) : pas de motif pour rien.
    int nq = 0;
    for (int k = 0; k < 4; k++) if (cand[k] == i2 && i2 != i0) nq++;
    // Autres trames : part de la 2e couleur par projection de la cible sur le segment des deux couleurs.
    float qp = 0.0;
    if (gType != 0 && i2 != i0){
      vec3 ab = gLab[i2] - gLab[i0];
      qp = clamp(dot(c[0] - gLab[i0], ab) / max(dot(ab, ab), 1e-6), 0.0, 0.5);
      if (gType == 4) qp = floor(qp * 4.0 + 0.5) / 4.0;
      if (gType == 5) qp = qp >= 0.25 ? 0.5 : 0.0;
      nq = qp > 0.0 ? 1 : 0;
    }
    if (nq > 0){
      float q = gType != 0 ? qp : float(nq) / 4.0;
      vec3 d = gLab[i2] - gLab[i0];
      float pen = 0.08 * pow(40.0, 1.0 - s) * dot(d, d) * q * (1.0 - q);
      if (perr(c[0], mix(gLab[i0], gLab[i2], q)) + pen >= perr(c[0], gLab[i0])){ for (int k = 0; k < 4; k++) cand[k] = i0; qp = 0.0; }
    }
    if (gType != 0){
      o = vec4(clamp(p >= 1 ? PAL[PAL_OFF[p - 1] + (trame(cell) < qp ? i2 : i0)] : uColor(trame(cell) < qp ? i2 : i0).rgb, 0.0, 1.0), 1.0);
      return;
    }
    for (int a = 0; a < 3; a++){
      for (int b = 0; b < 3; b++){
        if (b >= 3 - a) break;
        if (gLab[cand[b]].x > gLab[cand[b + 1]].x){ int tmp = cand[b]; cand[b] = cand[b + 1]; cand[b + 1] = tmp; }
      }
    }
    outI = cand[bayer2(cell)];
  }
  o = vec4(clamp(p >= 1 ? PAL[PAL_OFF[p - 1] + outI] : uColor(outI).rgb, 0.0, 1.0), 1.0);
}

// Pixels : mosaïque avec joints, résolution réglable.
void mainImage(out vec4 c, in vec2 p){
  vec2 uv = p / iResolution.xy;
  float n = max(8.0, uParam0);
  vec2 cells = vec2(n, n * iResolution.y / iResolution.x);
  vec2 q = (floor(uv * cells) + 0.5) / cells;
  vec3 col = texture(iChannel0, q).rgb;
  vec2 f = fract(uv * cells) - 0.5;
  col *= 1.0 - smoothstep(0.42, 0.5, max(abs(f.x), abs(f.y)));
  c = vec4(col, 1.0);
}

// Plasma : ondes colorées, le clic déplace le centre.
vec3 pal(float t){ return 0.5 + 0.5 * cos(6.28318 * (t + vec3(0.0, 0.33, 0.67))); }
void mainImage(out vec4 o, in vec2 f){
  vec2 p = (2.0 * f - iResolution.xy) / min(iResolution.x, iResolution.y);
  float t = iTime * uParam0;
  float s = uParam1;
  vec2 m = iMouse.z > 0.0 ? (2.0 * iMouse.xy - iResolution.xy) / min(iResolution.x, iResolution.y) : vec2(0.0);
  float v = sin(p.x * s + t) + sin(p.y * s * 1.3 - t * 1.1)
          + sin((p.x + p.y) * s * 0.7 + t * 0.7) + sin(length(p - m) * s * 1.6 - t * 1.4);
  vec3 col = pal(uParam2 + v * 0.15);
  col *= 0.75 + 0.25 * sin(v * 3.14159);
  o = vec4(col, 1.0);
}

// Fumée de scène : brume qui monte et dérive, grise sur noir (à poser en fusion « screen »).
// Bruit de valeur fractal, déformé par lui-même ; plus dense en bas, plus claire près du sol.
float hsh(vec2 p){ p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }
float vnoise(vec2 p){
  vec2 i = floor(p), f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hsh(i), hsh(i + vec2(1.0, 0.0)), f.x), mix(hsh(i + vec2(0.0, 1.0)), hsh(i + vec2(1.0, 1.0)), f.x), f.y);
}
float fbm(vec2 p){
  float a = 0.5, s = 0.0;
  for (int i = 0; i < 5; i++) { s += a * vnoise(p); p = p * 2.03 + vec2(17.1, 9.7); a *= 0.5; }
  return s;
}
void mainImage(out vec4 o, in vec2 f){
  vec2 uv = f / iResolution.xy;
  float asp = iResolution.x / iResolution.y;
  float t = iTime * uParam1;
  vec2 p = vec2(uv.x * asp, uv.y) * uParam2;
  // Deux passes de déformation : la fumée s'enroule au lieu de simplement glisser.
  vec2 q = vec2(fbm(p + vec2(0.0, -t * 0.6)), fbm(p + vec2(5.2, 1.3 - t * 0.5)));
  vec2 r = vec2(fbm(p + 2.0 * q + vec2(1.7, 9.2) + t * 0.15), fbm(p + 2.0 * q + vec2(8.3, 2.8) - t * 0.12));
  float n = fbm(p + 2.2 * r + vec2(0.0, -t));
  float d = smoothstep(0.30, 0.85, n);
  float low = mix(1.0, 0.45, uv.y);                 // plus dense près du sol
  float edge = smoothstep(0.0, 0.18, uv.x) * (1.0 - smoothstep(0.82, 1.0, uv.x));
  d *= uParam0 * low * (0.55 + 0.45 * edge);
  vec3 cool = vec3(0.80, 0.84, 0.92), warm = vec3(1.0, 0.86, 0.72);
  vec3 col = mix(cool, warm, uParam3) * (0.65 + 0.35 * n);
  o = vec4(col * d, 1.0);
}

// Contours de Sobel sur l'image du canal 0.
// Modes : 0 = contours blancs sur noir (sortie utilisable comme carte de contours
// par hough-lines / hough-circles), 1 = contours par-dessus l'image, 2 = direction du gradient en couleur.
float lum(vec3 c){ return dot(c, vec3(0.299, 0.587, 0.114)); }
float L(vec2 uv){ return lum(texture(iChannel0, uv).rgb); }
void mainImage(out vec4 o, in vec2 p){
  vec2 uv = p / iResolution.xy;
  vec2 t = max(uParam0, 1.0) / iChannelResolution[0].xy;
  float a = L(uv + t * vec2(-1.0, -1.0)), b = L(uv + t * vec2(0.0, -1.0)), c = L(uv + t * vec2(1.0, -1.0));
  float d = L(uv + t * vec2(-1.0, 0.0)),                                   f = L(uv + t * vec2(1.0, 0.0));
  float g = L(uv + t * vec2(-1.0, 1.0)),  h = L(uv + t * vec2(0.0, 1.0)),  i = L(uv + t * vec2(1.0, 1.0));
  float gx = (c + 2.0 * f + i) - (a + 2.0 * d + g);
  float gy = (g + 2.0 * h + i) - (a + 2.0 * b + c);
  float m = clamp(length(vec2(gx, gy)) * uParam1, 0.0, 1.0);
  int mode = int(uParam2 + 0.5);
  vec3 base = texture(iChannel0, uv).rgb;
  vec3 col = vec3(m);
  if (mode == 1) col = mix(base * 0.6, vec3(1.0, 0.9, 0.2), m);
  if (mode == 2) {
    float h6 = atan(gy, gx) / 6.2831853 + 0.5;
    vec3 hue = clamp(abs(mod(h6 * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
    col = hue * m;
  }
  o = vec4(col, 1.0);
}

// Fausse caméra thermique : luminance -> palette chaud/froid.
void mainImage(out vec4 c, in vec2 p){
  vec2 uv = p / iResolution.xy;
  vec3 col = texture(iChannel0, uv).rgb;
  float l = dot(col, vec3(0.299, 0.587, 0.114));
  vec3 t = clamp(vec3(1.6 * l - 0.3, sin(3.14159 * l) * 1.1, 1.0 - 1.8 * l), 0.0, 1.0);
  c = vec4(mix(col, t, uParam0), 1.0);
}

// Transition entre deux images : iChannel0 (départ) → iChannel1 (arrivée), pilotée par l'avancement.
// uParam0 avancement 0..1 ; uParam1 type : 0 fondu, 1 volet, 2 cercle, 3 dissolution, 4 pixels, 5 glissement,
// 6 zoom, 7 losanges ; uParam2 douceur du bord (0..0,5).
float th12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }

float tnoise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(th12(i), th12(i + vec2(1.0, 0.0)), u.x), mix(th12(i + vec2(0.0, 1.0)), th12(i + vec2(1.0, 1.0)), u.x), u.y);
}

void mainImage(out vec4 c, in vec2 p) {
  vec2 uv = p / iResolution.xy;
  float t = clamp(uParam0, 0.0, 1.0);
  int kind = int(floor(uParam1 + 0.5));
  float soft = clamp(uParam2, 0.001, 0.5);
  float aspect = iResolution.x / iResolution.y;
  vec2 ua = uv, ub = uv;
  float m = t;
  if (kind == 1) {
    // volet de gauche à droite, bord adouci
    m = smoothstep(uv.x - soft, uv.x, t * (1.0 + soft));
  } else if (kind == 2) {
    float d = length((uv - 0.5) * vec2(aspect, 1.0)) / length(vec2(aspect, 1.0) * 0.5);
    m = smoothstep(d - soft, d, t * (1.0 + soft));
  } else if (kind == 3) {
    float n = tnoise(uv * 12.0) * 0.65 + tnoise(uv * 40.0) * 0.35;
    m = smoothstep(n - soft, n, t * (1.0 + soft));
  } else if (kind == 4) {
    // pixels qui grossissent jusqu'au milieu puis s'affinent sur l'arrivée
    float k = 1.0 - abs(t * 2.0 - 1.0);
    float cells = mix(iResolution.y, 12.0, k);
    vec2 g = vec2(cells * aspect, cells);
    ua = ub = (floor(uv * g) + 0.5) / g;
    m = step(0.5, t);
  } else if (kind == 5) {
    float e = t * t * (3.0 - 2.0 * t);
    ua = uv + vec2(e, 0.0);
    ub = uv - vec2(1.0 - e, 0.0);
    m = step(1.0 - e, uv.x);
  } else if (kind == 6) {
    float e = t * t * (3.0 - 2.0 * t);
    ua = (uv - 0.5) / (1.0 + e * 1.5) + 0.5;
    ub = (uv - 0.5) * (1.0 + (1.0 - e) * 0.5) + 0.5;
    m = e;
  } else if (kind == 7) {
    vec2 q = fract(uv * vec2(aspect, 1.0) * 8.0) - 0.5;
    float d = (abs(q.x) + abs(q.y)) * 2.0;
    float sweep = t * 2.0 - uv.x * 0.8;
    m = smoothstep(d - soft, d, sweep);
  }
  vec4 a = texture(iChannel0, clamp(ua, 0.0, 1.0));
  vec4 b = texture(iChannel1, clamp(ub, 0.0, 1.0));
  c = vec4(mix(a.rgb, b.rgb, clamp(m, 0.0, 1.0)), 1.0);
}
